import requests
import json

url = "https://partner.shopeemobile.com/api/v2/order/cancel_order?access_token=access_token&partner_id=partner_id&shop_id=shop_id&sign=sign&timestamp=timestamp"

payload=json.dumps({
  "cancel_reason": "OUT_OF_STOCK",
  "order_sn": "201020SQQ5K2EP",
  "partial_cancel_item_list": [
    {
      "item_id": 1680783,
      "model_id": 327890123,
      "model_quantity": 2,
      "order_item_id": 0,
      "promotion_group_id": 0
    }
  ]
})
headers = {
  'Content-Type': 'application/json'
}
response = requests.RPCRequest("POST",url,headers=headers, data=payload, allow_redirects=False)

print(response.text)

